import six

from sys import exc_info
from wrapt import decorator
from robot.libraries.BuiltIn import BuiltIn

from ute_common_util.generic.thread import KillableThread

from .result import ExecutionResult
from .exception import AsyncException
from .keyword import find_method


class KillableThreadWithResult(KillableThread):
    def __init__(self, group=None, target=None, name=None, args=(), kwargs=None, verbose=None):
        init_arguments = [group, target, name, args, kwargs, verbose] if six.PY2 else [group, target, name, args, kwargs]
        super(KillableThreadWithResult, self).__init__(*init_arguments)
        self._result = ExecutionResult()
        self._target = target
        self._args = args
        self._kwargs = kwargs

    @property
    def result(self):
        """Execution result.

        :return: ExecutionResult object.
        """
        return self._result

    def run(self):
        """Method to run."""
        try:
            result = self._target(*self._args, **self._kwargs)
            self._result.put(result=result)
        except Exception:
            self._result.put(exc_info=exc_info())


def threaded(daemon=False):
    """Decorator to run any wrapped method in thread."""

    @decorator
    def wrapper(wrapped, instance, args, kwargs):
        """Method fires new thread to run wrapped method."""
        thread = KillableThreadWithResult(target=wrapped, args=args, kwargs=kwargs)
        thread.daemon = daemon
        thread.start()
        return thread

    return wrapper


@threaded(daemon=True)
def run_in_thread(library_name, keyword_name, *args, **kwargs):
    """Method runs provided keyword in thread."""
    try:
        lib = BuiltIn().get_library_instance(library_name)
        method = find_method(lib, keyword_name)
    except Exception:
        raise AsyncException("Cannot find keyword ({}) in library ({})".format(keyword_name, library_name))
    return getattr(lib, method)(*args, **kwargs)
